#  الموقع سيعمل على:  http://<عنوان-السيرفر>:5819
# ============================================================================
set -euo pipefail
APP=/opt/civil5819
PORT=5819

echo "==> [1/6] التحقق من بايثون"
command -v python3 >/dev/null || { apt-get update -y && apt-get install -y python3; }
